  a = unwrap(u:parse_action("WRITE doc.md\\n# Title\\n```sh\\njust check\\n```\\nmore\\nEND"));
  u:assert_text_eq(a.body, "# Title\\n```sh\\njust check\\n```\\nmore\\n", "inner fences kept")
