"""def u:parse_write(lines, start, path) {
  "Collect body lines after start up to END; err on missing END or text after it.";
  n = list_len(lines);
  i = start + 1;
  body = "";
  end_at = -1;
  while i < n {
    line = unwrap(list_get(lines, i));
    if str_eq(u:rtrim(line), "END") { end_at = i; break } else {
      body = str_concat(body, str_concat(line, "\\n"))
    };
    i = i + 1
  };
  if end_at < 0 { err("missing END after WRITE body") } else {
    u:rest_after(lines, end_at + 1)?;
    ok({tool: "write", path: path, body: body})
  }
}""",
"""def u:is_fence_line(line) {
  "1 when a line is only a markdown fence: three backticks, optionally followed by a language word.";
  trimmed = u:trim(line);
  if u:has_prefix(trimmed, "```") { if str_find(str_slice(trimmed, 3, str_len(trimmed)), " ") < 0 { 1 } else { 0 } } else { 0 }
}

def u:strip_outer_fences(body_lines) {
  "Drop a fence-only first line and a fence-only last line; inner fences are content.";
  n = list_len(body_lines);
  first = 0;
  last = n;
  if n > 0 { if u:is_fence_line(unwrap(list_get(body_lines, 0))) { first = 1 } else { 0 } } else { 0 };
  if last > first { if u:is_fence_line(unwrap(list_get(body_lines, last - 1))) { last = last - 1 } else { 0 } } else { 0 };
  body = "";
  i = first;
  while i < last {
    body = str_concat(body, str_concat(unwrap(list_get(body_lines, i)), "\\n"));
    i = i + 1
  };
  body
}

def u:parse_write(lines, start, path) {
  "Collect body lines after start up to END, strip outer fence lines; err on missing END or text after it.";
  n = list_len(lines);
  i = start + 1;
  raw = "";
  end_at = -1;
  while i < n {
    line = unwrap(list_get(lines, i));
    if str_eq(u:rtrim(line), "END") { end_at = i; break } else {
      raw = str_concat(raw, str_concat(line, "\\n"))
    };
    i = i + 1
  };
  if end_at < 0 { err("missing END after WRITE body") } else {
    u:rest_after(lines, end_at + 1)?;
    body = if str_len(raw) == 0 { "" } else {
      u:strip_outer_fences(str_split(str_slice(raw, 0, str_len(raw) - 1), "\\n"))
    };
    ok({tool: "write", path: path, body: body})
  }
}""")
print("protocol hardened")
