def u:parse_write(lines, start, path) {
  "Collect body lines after start up to END; err on missing END or text after it.";
  n = list_len(lines);
  i = start + 1;
  body = "";
  end_at = -1;
  while i < n {
    line = unwrap(list_get(lines, i));
    if str_eq(u:rtrim(line), "END") {
      end_at = i;
      break
    } else {
      body = str_concat(body, str_concat(line, "\n"))
    };
    i = i + 1
  };
  if end_at < 0 {
    err("missing END after WRITE body")
  } else {
    u:rest_after(lines, end_at + 1)?;
    ok({tool: "write", path: path, body: body})
  }
}

